const CLUB_TIER={...ARG_TIER};
Object.entries(NEW_CLUBS).forEach(([lg,arr])=>{CLUBS[lg]=arr.map(x=>x[0]);arr.forEach(x=>{CLUB_TIER[x[0]]=x[1]})});
