const LEAGUE_ORDER=['Argentina','Inglaterra','España','Italia','Alemania','Francia','Portugal','Países Bajos','Brasil','Estados Unidos','México','Arabia Saudita'];
const SLUG_OVERRIDE={'Bayern München':'bayern-munchen','Borussia Dortmund':'borussia-dortmund','AC Milan':'ac-milan','Inter':'inter-milan','Athletic Club':'athletic-club','Atlético de Madrid':'atletico-madrid','Paris Saint-Germain':'paris-saint-germain','Sporting CP':'sporting-cp','Pumas UNAM':'pumas-unam','Tigres UANL':'tigres-uanl','Guadalajara':'chivas-guadalajara','América':'club-america','Wolverhampton':'wolverhampton-wanderers','Brighton':'brighton-hove-albion','Newcastle':'newcastle-united','Tottenham':'tottenham-hotspur','West Ham':'west-ham-united','Manchester United':'manchester-united','Manchester City':'manchester-city','Celta':'celta-vigo','Betis':'real-betis','Mainz 05':'mainz-05','Stuttgart':'vfb-stuttgart','Hoffenheim':'tsg-hoffenheim','Freiburg':'sc-freiburg','Wolfsburg':'vfl-wolfsburg','Union Berlin':'union-berlin','Werder Bremen':'werder-bremen','FC Köln':'fc-koln','Hamburger SV':'hamburger-sv','St. Pauli':'fc-st-pauli','Heidenheim':'fc-heidenheim','Eintracht Frankfurt':'eintracht-frankfurt','RB Leipzig':'rb-leipzig','Bayer Leverkusen':'bayer-leverkusen','Borussia Mönchengladbach':'borussia-monchengladbach','Augsburg':'fc-augsburg','AZ':'az-alkmaar','Twente':'fc-twente','Utrecht':'fc-utrecht','Heerenveen':'sc-heerenveen','PSV':'psv-eindhoven','Ajax':'ajax','Feyenoord':'feyenoord','Vitória SC':'vitoria-guimaraes','Vitória':'ec-vitoria','Braga':'sc-braga','Bragantino':'red-bull-bragantino','Vasco da Gama':'vasco-da-gama','Sport Recife':'sport-recife','Atlético Mineiro':'atletico-mineiro','LAFC':'los-angeles-fc','LA Galaxy':'la-galaxy','DC United':'dc-united','CF Montréal':'cf-montreal','New York City FC':'new-york-city-fc','New York Red Bulls':'new-york-red-bulls','Al-Hilal':'al-hilal','Al-Nassr':'al-nassr','Al-Ittihad':'al-ittihad','Al-Ahli':'al-ahli-saudi','NEOM':'neom-sc'};
const _kebab=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
function clubBadge(name,size=34){
 const initials=name.split(/\s+/).map(x=>x[0]).join('').slice(0,3);
 const slug=ARG_BADGES[name]||SLUG_OVERRIDE[name]||_kebab(name);
 const isArg=CLUBS.Argentina.includes(name);
 const url=isArg?`assets/escudos/${slug}.png`:`https://www.footylogos.com/dls/logo/rgba-v1/${slug}.png`;
 return `<span class="badge-wrap" style="width:${size}px;height:${size}px"><img class="club-badge" src="${url}" alt="Escudo ${name}" loading="lazy" referrerpolicy="no-referrer" onerror="this.style.display='none';this.nextElementSibling.style.display='inline-flex'"><span class="club-badge-fallback" style="width:${size}px;height:${size}px;display:none">${initials}</span></span>`;
}
function clubCountry(club){for(const k in CLUBS){if(CLUBS[k].includes(club))return k}return 'Argentina'}
function genericRoster(club){return [];}
function padRoster(raw,club){return (Array.isArray(raw)?raw:[]).filter(x=>x&&x[0]).map(x=>x.slice())}
function leagueName(c){return (LEAGUES[c]||{}).nombre||c}
function leagueInfoHTML(c){const L=LEAGUES[c];if(!L)return '';return `<b style="color:var(--gold)">${L.nombre}</b> · ${CLUBS[c].length} equipos · ${L.fecha} fechas<br>${L.formato}<br><span class="tiny">${L.cont}${L.desc?` · Descienden ${L.desc}`:' · Sin descenso'} · Copa: ${L.copa}</span>`}
function buildLeagueUI(){
 const sel=$('country');if(sel)sel.innerHTML=LEAGUE_ORDER.map(c=>`<option value="${c}">${LEAGUES[c].nombre} (${c})</option>`).join('');
 const box=document.querySelector('.x-leagues');
 if(box)box.innerHTML=LEAGUE_ORDER.map((c,i)=>`<button class="x-lg${i===0?' sel':''}" data-c="${c}" onclick="selectHomeLeague('${c}')"><i style="background:${LEAGUES[c].color}">${LEAGUES[c].abrev}</i>${LEAGUES[c].nombre.toUpperCase().replace(/ /,'<br>')}</button>`).join('');
}

let career=null,match=null,selectedSpot=null,leagueView='table',negotiationLog=[];
function defaultPlayers(club){return (ROSTERS[club]||[]).filter(p=>p&&p[0]).map((p,i)=>({id:i+1,name:p[0],pos:p[1],rating:p[2],potential:p[2],age:p[3]||25,fitness:90,morale:80,goals:0,assists:0,apps:0,contract:2,wage:Math.round(p[2]*.035*10)/10,number:i+1,pace:60,shooting:60,passing:60,defending:60,stamina:70,strength:65,injury:null,personality:'Profesional',foot:'Derecho',weakFoot:3}));}
function fillClubs(){let c=$('country').value;$('clubChoice').innerHTML=CLUBS[c].map(x=>`<option>${x}</option>`).join('');showClubBadge();const li=$('leagueInfo');if(li)li.innerHTML=leagueInfoHTML(c)}
function showClubBadge(){let el=$('clubBadgePreview');if(el&&$('clubChoice'))el.innerHTML=clubBadge($('clubChoice').value,42)}
function createCareer(){let club=$('clubChoice').value,country=$('country').value;career={club,country,manager:$('manager').value.trim()||'Entrenador',difficulty:$('difficulty').value,season:2026,round:0,played:0,w:0,d:0,l:0,gf:0,ga:0,points:0,budget:$('difficulty').value==='Experto'?32:$('difficulty').value==='Difícil'?48:65,board:78,stadium:2,academy:1,training:1,formation:'4-3-3',style:'Equilibrado',tempo:'Normal',line:'Media',players:defaultPlayers(club),history:[],academyPlayers:[],scouting:[],staff:{coach:2,scout:1,medical:1,analyst:1},facilities:{trainingPitches:1,gym:1,medical:1,analysis:1,residence:1},sponsors:[{name:'Patrocinador principal',income:3,level:1}],pressReputation:50,clubReputation:50,youthIntake:0,debts:0,inbox:['La directiva te da la bienvenida. El objetivo es clasificar a una copa continental.','El área de scouting está lista para recibir tus indicaciones.'],scorers:[],next:CLUBS[country].find(x=>x!==club)||'Rival FC',lastResult:null};match=null;save();renderAll();go('dashboard')}
function save(){localStorage.setItem('modo_carrera_41',JSON.stringify(career))}
function go(id){document.body.classList.toggle('home-mode',id==='home');document.body.classList.toggle('match-mode',id==='match');if(!career&&!['home','newcareer','more','saves','players','backup'].includes(id)){id='newcareer'}document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id===id));document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.go===id||(id==='dashboard'&&b.dataset.go==='dashboard')));if(id==='dashboard')renderDashboard();if(id==='tactics')renderTactics();if(id==='squad')renderSquad();if(id==='market')renderMarket();if(id==='league')renderLeague();if(id==='board')renderBoard();if(id==='advanced')renderAdvanced();if(id==='match')renderMatch();if(id==='home')renderHome();applyLanguage();window.scrollTo(0,0)}
function renderHome(){if(window.xTop)xTop()}
function fixtureHTML(){let opp=opponent();return `<div class="fixture"><div class="between"><div class="flex"><div>${clubBadge(career.club,36)}</div><div><div class="clubtitle">${career.club}</div><div class="tiny muted">LOCAL</div></div></div><b class="gold">VS</b><div class="flex"><div style="text-align:right"><div class="clubtitle">${opp}</div><div class="tiny muted">VISITANTE</div></div><div>${clubBadge(opp,36)}</div></div></div><div class="between tiny muted"><span>LIGA · FECHA ${career.round+1}</span><span>DOMINGO · 18:00</span></div></div>`}
function opponent(){let pool=CLUBS[career.country].filter(c=>c!==career.club);return pool[career.round%pool.length]||'Rival FC'}
function renderDashboard(){if(!career)return;$('dashClub').textContent=career.club;$('dashCrest').innerHTML=clubBadge(career.club,48);$('dashManager').textContent=`${career.manager} · ${career.country}`;$('dashPoints').textContent=career.points;$('dashRank').textContent=rank();$('dashBudget').textContent=`$${career.budget}M`;$('roundTag').textContent=`FECHA ${career.round+1}`;$('dashFixture').innerHTML=fixtureHTML();$('boardValue').textContent=career.board+'%';$('boardBar').style.width=career.board+'%';$('boardText').textContent=career.board>65?'La directiva respalda tu proyecto.':career.board>40?'Se esperan mejores resultados.':'Tu puesto está en riesgo.';$('squadPower').textContent=avgRating();$('recentForm').innerHTML=(career.history.slice(-5).map(x=>`<span class="${x.result.toUpperCase()}">${x.result.toUpperCase()}</span>`).join('')||'<span class="tag">SIN PARTIDOS</span>');$('clubNews').innerHTML=`<div class="news"><div class="newsicon">📊</div><div><b>${career.w} victorias en la temporada</b><p>Balance actual: ${career.w} ganados, ${career.d} empatados y ${career.l} perdidos.</p></div></div><div class="news"><div class="newsicon">💰</div><div><b>Situación financiera</b><p>Presupuesto disponible: $${career.budget} millones. Controlá los salarios.</p></div></div>`}
function rank(){return Math.max(1,10-Math.floor(career.points/4))}
function avgRating(){return Math.round(career.players.reduce((a,p)=>a+p.rating,0)/career.players.length)}
function renderTactics(){if(!career)return;$('formation').value=career.formation;$('tacticStyle').value=career.style;$('tempo').value=career.tempo;$('defLine').value=career.line;let coords=positions(career.formation);$('tacticalPitch').querySelectorAll('.spot').forEach(e=>e.remove());career.players.slice(0,11).forEach((p,i)=>{let c=coords[i]||coords[10];let b=document.createElement('button');b.className='spot'+(selectedSpot===i?' selected':'');b.style.left=c[0]+'%';b.style.top=c[1]+'%';b.innerHTML=`<b>${p.number}</b><small>${p.pos}</small>`;b.title=p.name;b.onclick=()=>selectSpot(i);$('tacticalPitch').appendChild(b)});$('selectedPlayer').textContent=selectedSpot===null?'Tocá un jugador y luego otro para intercambiar sus posiciones.':`Seleccionado: ${career.players[selectedSpot].name}. Ahora tocá otro jugador.`;$('tacticReadout').innerHTML=`<div class="statsrow"><span>Estilo</span><b>${career.style}</b></div><div class="statsrow"><span>Ritmo</span><b>${career.tempo}</b></div><div class="statsrow"><span>Línea defensiva</span><b>${career.line}</b></div><div class="statsrow"><span>Valoración media</span><b>${avgRating()}</b></div>`}
function positions(f){let defs={'4-3-3':[[50,88],[17,68],[39,73],[61,73],[83,68],[34,49],[50,55],[66,49],[18,25],[50,15],[82,25]],'4-2-3-1':[[50,88],[17,68],[39,73],[61,73],[83,68],[39,57],[61,57],[20,35],[50,38],[80,35],[50,15]],'4-4-2':[[50,88],[17,68],[39,73],[61,73],[83,68],[18,48],[39,51],[61,51],[82,48],[38,19],[62,19]],'3-5-2':[[50,88],[27,72],[50,75],[73,72],[12,49],[32,51],[50,55],[68,51],[88,49],[38,20],[62,20]],'5-3-2':[[50,88],[12,68],[31,72],[50,74],[69,72],[88,68],[32,49],[50,54],[68,49],[38,20],[62,20]],'4-1-4-1':[[50,88],[17,68],[39,73],[61,73],[83,68],[50,61],[18,43],[39,46],[61,46],[82,43],[50,17]],'3-4-3':[[50,88],[27,72],[50,75],[73,72],[15,48],[39,52],[61,52],[85,48],[18,22],[50,17],[82,22]]};return defs[f]||defs['4-3-3']}
function selectSpot(i){if(selectedSpot===null){selectedSpot=i}else if(selectedSpot===i){selectedSpot=null}else{[career.players[selectedSpot],career.players[i]]=[career.players[i],career.players[selectedSpot]];selectedSpot=null;save()}renderTactics()}
function setFormation(v){career.formation=v;save();renderTactics()}
function saveTactic(){career.style=$('tacticStyle').value;career.tempo=$('tempo').value;career.line=$('defLine').value;save();renderTactics()}
function autoLineup(){career.players.sort((a,b)=>b.rating-a.rating);career.players.forEach((p,i)=>p.number=i+1);save();renderTactics();alert('Alineación recomendada aplicada.')}
function renderSquad(){if(!career)return;$('squadCount').textContent=career.players.length;$('squadAvg').textContent=avgRating();$('squadFit').textContent=Math.round(career.players.reduce((a,p)=>a+p.fitness,0)/career.players.length)+'%';$('squadList').innerHTML=career.players.map((p,i)=>`<div class="playerrow"><div class="rating">${p.rating}</div><div onclick="openPlayer(${i})"><div class="playername">${p.name}</div><div class="pos">${p.pos} · ${p.age} años · POT ${p.potential}</div><div class="tiny muted">Físico ${p.fitness}% · Moral ${p.morale}%</div></div><button class="btn secondary small" onclick="openPlayer(${i})">VER</button></div>`).join('');renderLineupV6()}
function renderLineupV6(){let pitch=$('lineupPitchV6'),subs=$('lineupSubsV6');if(!pitch||!subs||!career)return;let coords=positions(career.formation||'4-3-3');pitch.innerHTML='';career.players.slice(0,11).forEach((p,i)=>{let c=coords[i]||[50,90-i*5];let el=document.createElement('button');el.className='lineup-player-v6';el.style.left=c[0]+'%';el.style.top=c[1]+'%';el.innerHTML=`<b>${p.number||i+1}</b><span>${p.name}</span><small>${p.pos}</small>`;el.onclick=()=>openPlayer(i);pitch.appendChild(el)});subs.innerHTML=career.players.slice(11).map((p,j)=>`<button class="sub-player-v6" onclick="openPlayer(${j+11})"><b>${p.number||j+12}</b><span>${p.name}</span><small>${p.pos} · ${p.rating}</small></button>`).join('')||'<span class="muted tiny">Todavía no hay suplentes disponibles.</span>'}
function openPlayer(i){let p=career.players[i];$('playerProfile').innerHTML=`<div class="card"><div class="between"><div><div class="eyebrow">${p.pos} · DORSAL ${p.number}</div><h1>${p.name}</h1><p>${career.club} · ${p.age} años</p></div><div class="rating" style="font-size:25px;padding:12px">${p.rating}</div></div><div class="metric-grid"><div class="metric"><b>${p.potential}</b><small>POTENCIAL</small></div><div class="metric"><b>${p.goals}</b><small>GOLES</small></div><div class="metric"><b>${p.assists}</b><small>ASIST.</small></div></div><div class="line"></div><div class="statsrow"><span>Estado físico</span><b>${p.fitness}%</b></div><div class="statbar"><span style="width:${p.fitness}%"></span></div><div class="statsrow"><span>Moral</span><b>${p.morale}%</b></div><div class="statbar"><span style="width:${p.morale}%"></span></div><div class="statsrow"><span>Edad</span><b>${p.age} años</b></div><div class="statsrow"><span>Contrato</span><b>${p.contract} temporadas</b></div><div class="statsrow"><span>Salario anual</span><b>$${p.wage.toFixed(1)}M</b></div><div class="statsrow"><span>Partidos disputados</span><b>${p.apps}</b></div><div class="statsrow"><span>Valor estimado</span><b>$${p.value!=null?p.value:Math.round(p.rating*p.rating/100)}M</b></div>
<h3>Atributos</h3>${[['Ritmo',p.pace||60],['Tiro',p.shooting||60],['Pase',p.passing||60],['Defensa',p.defending||60],['Resistencia',p.stamina||70],['Fuerza',p.strength||65]].map(a=>`<div class="statsrow"><span>${a[0]}</span><b>${a[1]}</b></div><div class="statbar"><span style="width:${a[1]}%"></span></div>`).join('')}
<div class="grid2"><button class="btn secondary" onclick="trainPlayer(${i})">ENTRENAR</button><button class="btn secondary" onclick="recoverPlayer(${i})">RECUPERAR</button></div>
<div class="grid2"><button class="btn secondary" onclick="renewPlayer(${i})">RENOVAR</button><button class="btn danger" onclick="listPlayerSale(${i})">TRANSFERIBLE</button></div>
<button class="btn secondary" style="width:100%;margin-top:14px" onclick="go('squad')">VOLVER AL PLANTEL</button></div>`;go('player')}
function renderMarket(){if(!career)return;$('marketBudget').textContent=`$${career.budget}M`;$('marketCount').textContent=MARKET.length;$('marketWindow').textContent='ABIERTO';let q=$('searchPlayer').value.toLowerCase(),pos=$('filterPos').value,min=+$('filterRating').value;let list=MARKET.filter(p=>p[0].toLowerCase().includes(q)&&(!pos||p[1]===pos)&&p[2]>=min);$('marketList').innerHTML=list.map((p,i)=>`<div class="playerrow"><div class="rating">${p[2]}</div><div><div class="playername">${p[0]}</div><div class="pos">${p[1]} · ${Math.max(19,30-p[2]%10)} años · POT ${Math.min(99,p[2]+8)}</div><div class="tiny muted">Valor estimado $${p[3]}M · Salario $${(p[2]*.04).toFixed(1)}M/año</div></div><button class="btn small" onclick="offerPlayer('${p[0]}',${p[1]==='POR'?0:1},${p[2]},${p[3]})">OFERTAR</button></div>`).join('')||'<p>No hay jugadores con esos filtros.</p>'}
function offerPlayer(name,_,rating,value){let price=Math.round(value*(career.difficulty==='Experto'?1.25:1.08));if(career.budget<price){alert('No alcanza el presupuesto para esta oferta.');return}openModal(`<div class="eyebrow">PROPUESTA DE FICHAJE</div><h2>${name}</h2><p>GRL ${rating} · Valor estimado $${value}M</p><label>Oferta al club ($M)</label><input id="offerPrice" type="number" value="${price}" min="1"><label>Duración del contrato</label><select id="offerYears"><option>3</option><option>2</option><option>4</option><option>5</option></select><button class="btn" style="width:100%" onclick="submitOffer('${name}',${rating},${value})">ENVIAR OFERTA</button><button class="btn ghost" style="width:100%;margin-top:8px" onclick="closeModal()">CANCELAR</button>`)}
function submitOffer(name,rating,value){let offer=+$('offerPrice').value,years=+$('offerYears').value;if(offer<=0){alert('Ingresá una oferta válida.');return}if(offer>career.budget){alert('La oferta supera tu presupuesto.');return}let chance=Math.min(.95,Math.max(.08,.35+(offer-value)/Math.max(value,1)*.7+(career.board-50)/250));if(Math.random()<chance){career.budget-=offer;let p={id:Date.now(),name,pos:MARKET.find(x=>x[0]===name)[1],rating,potential:Math.min(99,rating+8),age:23,fitness:95,morale:82,goals:0,assists:0,apps:0,contract:years,wage:Math.round(rating*.04*10)/10,number:career.players.length+1};career.players.push(p);negotiationLog.unshift(`✅ ${name} fichó por $${offer}M (${years} temporadas).`);career.inbox.unshift(`¡Fichaje confirmado! ${name} se incorpora al plantel.`)}else{negotiationLog.unshift(`❌ ${name}: oferta de $${offer}M rechazada.`);career.inbox.unshift(`El club de ${name} rechazó nuestra propuesta.`)}save();closeModal();renderMarket();$('negotiations').innerHTML=negotiationLog.slice(0,6).map(x=>`<div class="statsrow">${x}</div>`).join('')||'<p>Todavía no hay ofertas.</p>'}
function openMatch(){if(!career){go('newcareer');return}if(!match||match.finished)createMatch();go('match')}
function createMatch(){matchPaused=false;matchSpeed=2;
 let opp=opponent();let pool=ROSTERS[opp]||[];
 let rival=pool.map((p,i)=>({name:p[0],pos:p[1],rating:p[2]}));
 let own=career.players.slice(0,11);
 match={home:career.club,away:opp,minute:0,h:0,a:0,shotsH:0,shotsA:0,pos:50,cornersH:0,cornersA:0,foulsH:0,foulsA:0,yH:0,yA:0,xgH:0,xgA:0,events:[],done:false,moments:0,rivalPlayers:rival,ownPlayers:own,scorers:[],assists:[],ratings:{},subs:0};
}
function playMoment(){
 if(match.done||matchPaused)return;let max=$('matchLength').value==='quick'?10:$('matchLength').value==='long'?22:16;
 if(match.moments>=max){finishMatch();return}match.moments++;match.minute=match.moments===1?5:Math.min(90,Math.round(match.moments*90/max));
 let homeAttack=Math.random()<(match.pos/100),r=Math.random(),msg='',title='',att,def;
 let own=match.ownPlayers,rival=match.rivalPlayers;
 let formationBonus=career.formation==='4-3-3'?.025:career.formation==='4-2-3-1'?.015:0;
 let press=career.style==='Presión alta'?.07:0, counter=career.style==='Contraataque'?.05:0, defensive=career.style==='Defensivo'?.055:0;
 let midfield=own.filter(p=>p.pos==='MED').reduce((a,p)=>a+p.rating,0)/Math.max(1,own.filter(p=>p.pos==='MED').length);
 let forwards=own.filter(p=>p.pos==='DEL').sort((a,b)=>b.rating-a.rating);let defenders=rival.filter(p=>p.pos==='DEF');
 let oppMid=rival.filter(p=>p.pos==='MED').reduce((a,p)=>a+p.rating,0)/Math.max(1,rival.filter(p=>p.pos==='MED').length);
 if(homeAttack){att=forwards[0]||own[0];def=defenders[0]||rival[0]}else{att=rival.filter(p=>p.pos==='DEL').sort((a,b)=>b.rating-a.rating)[0]||rival[0];def=own.filter(p=>p.pos==='DEF').sort((a,b)=>b.rating-a.rating)[0]||own[0]}
 let tacticalEdge=homeAttack?((midfield-oppMid)/200)+formationBonus+press+counter:(-defensive*.45);
 if(r<.31){let shot=homeAttack?att:(att||rival[0]);let keeper=homeAttack?(rival.find(p=>p.pos==='POR')||rival[0]):(own.find(p=>p.pos==='POR')||own[0]);let chance=Math.max(.06,Math.min(.52,.19+(shot.rating-75)*.012+(homeAttack?tacticalEdge:0)+(career.tempo==='Alto'?.025:0)-(career.line==='Alta'&&!homeAttack?.025:0)));
 if(homeAttack){match.shotsH++;match.xgH+=chance*.9;let scored=Math.random()<chance;if(scored){match.h++;let assist=own.filter(p=>p!==shot&&p.pos==='MED').sort((a,b)=>b.rating-a.rating)[0];shot.goals=(shot.goals||0)+1;if(assist)assist.assists=(assist.assists||0)+1;match.scorers.push(shot.name);match.events.unshift({min:match.minute,title:'⚽ GOL LOCAL',msg:`¡GOOOL! ${shot.name} define para ${career.club}${assist?' tras la asistencia de '+assist.name:''}.`});return afterMoment()}msg=`${shot.name} remata al arco, pero ${keeper.name} responde con una gran atajada.`;title='OCASIÓN DE GOL';}
 else{match.shotsA++;match.xgA+=chance*.9;let scored=Math.random()<Math.max(.05,chance-defensive*.6);if(scored){match.a++;match.events.unshift({min:match.minute,title:'GOL VISITANTE',msg:`¡Gol de ${shot.name} para ${match.away}! ${keeper.name} no logra evitarlo.`});return afterMoment()}msg=`${shot.name} prueba al arco y ${keeper.name} contiene el remate.`;title='ATAJADA DEL ARQUERO';}}
 else if(r<.44){if(homeAttack)match.cornersH++;else match.cornersA++;title='TIRO DE ESQUINA';let taker=homeAttack?(own.find(p=>p.pos==='MED')||att):(rival.find(p=>p.pos==='MED')||att);msg=`Córner para ${homeAttack?career.club:match.away}. ${taker.name} se prepara para ejecutarlo.`}
 else if(r<.53){if(homeAttack)match.yA++;else match.yH++;title='TARJETA AMARILLA';let booked=homeAttack?(rival.find(p=>p.pos==='DEF')||def):(own.find(p=>p.pos==='DEF')||def);msg=`${booked.name} recibe tarjeta amarilla por una entrada fuerte.`}
 else if(r<.62){if(homeAttack)match.foulsA++;else match.foulsH++;title='FALTA';let fouled=homeAttack?att:def;msg=`Falta sobre ${fouled.name}. El árbitro detiene el juego.`}
 else{title='JUEGO EN DESARROLLO';if(homeAttack){let creator=own.filter(p=>p.pos==='MED').sort((a,b)=>b.rating-a.rating)[0]||att;msg=`${creator.name} conduce el ataque de ${career.club} y busca a ${att.name} en profundidad.`}else{let creator=rival.find(p=>p.pos==='MED')||att;msg=`${creator.name} organiza la salida de ${match.away}; ${def.name} ordena la defensa.`}}
 match.pos=Math.max(25,Math.min(75,match.pos+(Math.random()*8-4)+(career.style==='Posesión'?3:career.style==='Defensivo'?-2:career.style==='Presión alta'?1:0)+(career.tempo==='Alto'?1:0)));
 match.events.unshift({min:match.minute,title,msg});afterMoment();
 function afterMoment(){$('commentTitle').textContent=match.events[0].title;$('commentText').textContent=match.events[0].msg;renderMatch();if(match.moments>=max)$('matchAction').textContent='VER RESULTADO FINAL →'}
}
let matchPaused=false,matchSpeed=2;
function toggleMatchPause(){matchPaused=!matchPaused;let b=$('pauseMatchBtn');if(b){b.textContent=matchPaused?'▶ REANUDAR':'Ⅱ PAUSAR';b.classList.toggle('active',matchPaused)}$('matchAction').disabled=matchPaused;$('matchAction').style.opacity=matchPaused?'.45':'1'}
function setMatchSpeed(n,el){matchSpeed=n;document.querySelectorAll('.match-controls .match-control').forEach(b=>{if(b.textContent.includes('x2')||b.textContent.includes('x4')||b.textContent.includes('x8'))b.classList.remove('active')});if(el)el.classList.add('active');}
function openMatchSubs(){if(!career)return;let available=career.players.filter(p=>!p.injury).slice(0,18);openModal(`<div class="between"><h2>Cambios y sustituciones</h2><button class="btn small secondary" onclick="closeModal()">CERRAR</button></div><p>Elegí un jugador disponible para realizar una sustitución.</p>${available.map((p,i)=>`<div class="statsrow"><span>${p.name} · ${p.pos}</span><button class="btn small" onclick="makeMatchSub(${i})" ${match.subs>=5?'disabled':''}>INGRESAR</button></div>`).join('')}<p class="tiny">Cambios realizados: ${match.subs||0}/5. Esta acción actualiza el registro de sustituciones de la partida.</p>`)}
function makeMatchSub(i){if(match.subs>=5){alert('Ya realizaste los 5 cambios permitidos.');return}let p=career.players.filter(x=>!x.injury).slice(0,18)[i];if(!p)return;match.subs++;match.events.unshift({min:match.minute||0,title:'🔁 CAMBIO',msg:`${p.name} ingresa al campo.`});closeModal();renderMatch()}
function renderMatch(){if(!match)return;$('homeTeam').textContent=match.home;$('awayTeam').textContent=match.away;$('score').textContent=`${match.h} - ${match.a}`;$('matchMinute').textContent=match.moments?`${match.minute}’`:'PREVIA';$('matchClock').textContent=match.moments?`${String(Math.floor(match.minute*60/90)).padStart(2,'0')}:${String((match.minute*60)%60).padStart(2,'0')}`:'00:00';$('matchState').textContent=match.done?'FINALIZADO':match.moments?'EN JUEGO':'EN VESTUARIOS';$('matchPhase').textContent=match.done?'FINAL':match.moments?'PARTIDO EN JUEGO':'PREPARADOS';$('matchComp').textContent=`${career.country.toUpperCase()} · FECHA ${career.round+1}`;$('matchAction').textContent=match.done?'JUGAR SIGUIENTE FECHA →':match.moments?'SIGUIENTE JUGADA · x'+matchSpeed:'COMENZAR PARTIDO →';$('matchAction').onclick=()=>match.done?nextFixture():playMoment();$('matchAction').disabled=matchPaused;
let statData=[['Posesión',Math.round(match.pos)+'%',(100-Math.round(match.pos))+'%',match.pos],['Remates',match.shotsH,match.shotsA,match.shotsH+match.shotsA?match.shotsH/(match.shotsH+match.shotsA)*100:50],['Córners',match.cornersH,match.cornersA,match.cornersH+match.cornersA?match.cornersH/(match.cornersH+match.cornersA)*100:50],['Faltas',match.foulsH,match.foulsA,match.foulsH+match.foulsA?match.foulsH/(match.foulsH+match.foulsA)*100:50],['Amarillas',match.yH,match.yA,match.yH+match.yA?match.yH/(match.yH+match.yA)*100:50],['xG',match.xgH.toFixed(2),match.xgA.toFixed(2),match.xgH+match.xgA?match.xgH/(match.xgH+match.xgA)*100:50]];$('matchStats').innerHTML=statData.map(x=>`<div class="match-stat"><div class="match-stat-label"><span>${x[0]}</span><b>${x[1]} · ${x[2]}</b></div><div class="match-stat-bar"><i style="width:${x[3]}%"></i></div></div>`).join('');$('matchEvents').innerHTML=match.events.slice(0,5).map(e=>`<div class="match-event-row"><span class="match-event-minute">${e.min}'</span><div><div class="match-event-title">${e.title}</div><div class="match-event-msg">${e.msg}</div></div></div>`).join('')||'<div class="match-event-row"><span class="match-event-minute">--’</span><div><div class="match-event-title">A la espera del inicio</div><div class="match-event-msg">El público espera el comienzo.</div></div></div>';$('commentTitle').textContent=match.events[0]?.title||'TODO LISTO';$('commentText').textContent=match.events[0]?.msg||'El equipo está preparado. Es momento de salir a la cancha.'}

function finishMatch(){if(match.done)return;match.done=true;let res=match.h>match.a?'W':match.h===match.a?'D':'L';career.played++;career.round++;career.gf+=match.h;career.ga+=match.a;career.w+=res==='W';career.d+=res==='D';career.l+=res==='L';career.points+=res==='W'?3:res==='D'?1:0;career.history.push({result:res,h:match.h,a:match.a,opp:match.away});career.budget+=res==='W'?2:res==='D'?1:0;career.board=Math.max(5,Math.min(99,career.board+(res==='W'?4:res==='D'?1:-5)));career.players.forEach((p,i)=>{p.apps++;p.fitness=Math.max(42,p.fitness-8-Math.floor(Math.random()*8));if(!p.injury&&p.fitness<55&&Math.random()<.018){p.injury='Lesión muscular · 2 semanas';career.inbox.unshift(p.name+' sufrió una lesión muscular.');}p.morale=Math.max(35,Math.min(99,p.morale+(res==='W'?4:res==='L'?-5:1)));if(p.pos==='DEL'&&Math.random()<.18)p.goals++});let best=match.ownPlayers.slice(0,11);$('ratingsList').innerHTML=best.map(p=>`<div class="statsrow"><span>${p.name}</span><b>${(6.2+Math.random()*2.8).toFixed(1)}</b></div>`).join('')+match.rivalPlayers.slice(0,5).map(p=>`<div class="statsrow"><span>${p.name} <span class="muted">(${match.away})</span></span><b>${(6.0+Math.random()*2.5).toFixed(1)}</b></div>`).join('');match.events.unshift({min:90,title:'FINAL DEL PARTIDO',msg:`${match.home} ${match.h}-${match.a} ${match.away}. ${res==='W'?'Gran victoria.':res==='D'?'Reparto de puntos.':'Derrota. A trabajar.'}`});save();$('commentTitle').textContent='FINAL DEL PARTIDO';$('commentText').textContent=`${match.home} ${match.h} - ${match.a} ${match.away}. ${res==='W'?'¡Victoria!':res==='D'?'Empate.':'Derrota.'}`;$('matchAction').textContent='JUGAR SIGUIENTE FECHA →';$('matchAction').onclick=nextFixture;$('matchState').textContent='FINALIZADO';$('matchMinute').textContent='90’ · FINAL';$('matchEvents').innerHTML=match.events.map(e=>`<div class="statsrow"><span class="gold">${e.min}' · ${e.title}</span><b style="font-weight:500;text-align:right;max-width:65%">${e.msg}</b></div>`).join('');renderHome();renderDashboard()}
function nextFixture(){match=null;career.players.forEach(p=>{p.fitness=Math.min(100,p.fitness+12);if(p.injury){p.injury=null;p.fitness=Math.min(75,p.fitness)}});save();openMatch()}
function leagueTab(tab,el){leagueView=tab;document.querySelectorAll('.tabs button').forEach(b=>b.classList.remove('active'));el.classList.add('active');renderLeague()}
function renderLeague(){if(!career)return;let rows=[{name:career.club,pts:career.points,pj:career.played,gf:career.gf,ga:career.ga,you:true},...CLUBS[career.country].filter(x=>x!==career.club).map((n,i)=>({name:n,pts:Math.max(0,12-i*2+Math.floor(career.round/2)),pj:career.round,gf:career.round*2,ga:career.round+1}))].sort((a,b)=>b.pts-a.pts);if(leagueView==='table')$('leagueContent').innerHTML=`<div class="card"><h2>${leagueName(career.country)}</h2><p class="tiny">${(LEAGUES[career.country]||{}).formato||''}</p><table class="table"><tr><th># Club</th><th>PTS</th><th>PJ</th><th>GF</th><th>GC</th></tr>${rows.map((r,i)=>`<tr class="${r.you?'you':''}"><td><span style="display:inline-flex;align-items:center;gap:6px">${clubBadge(r.name,22)} ${i+1}. ${r.name}</span></td><td>${r.pts}</td><td>${r.pj}</td><td>${r.gf}</td><td>${r.ga}</td></tr>`).join('')}</table><p class="tiny">Tabla simulada para esta partida; los resultados de tu club sí se actualizan al jugar.</p></div>`;else if(leagueView==='calendar')$('leagueContent').innerHTML=`<div class="card"><h2>Calendario y resultados</h2>${Array.from({length:CLUBS[career.country].length-1},(_,i)=>{let h=career.history[i];return `<div class="statsrow"><span>Fecha ${i+1} · ${career.club} vs ${CLUBS[career.country].filter(x=>x!==career.club)[i]}</span><b>${h?h.h+' - '+h.a:'Pendiente'}</b></div>`}).join('')}</div>`;else if(leagueView==='scorers')$('leagueContent').innerHTML=`<div class="card"><h2>Goleadores del equipo</h2>${[...career.players].sort((a,b)=>b.goals-a.goals).slice(0,10).map(p=>`<div class="statsrow"><span>${p.name}</span><b>${p.goals} goles</b></div>`).join('')}</div>`;else $('leagueContent').innerHTML=`<div class="card"><div class="eyebrow">COPA NACIONAL</div><h2>Camino a la final</h2><p>${(LEAGUES[career.country]||{}).copa||'Copa nacional'}: la copa se habilitará como competición eliminatoria en una próxima etapa. Por ahora podés seguir la liga y sus estadísticas.</p><p class="tiny">Clasificación continental: ${(LEAGUES[career.country]||{}).cont||''}</p><span class="pill">FORMATO · ELIMINACIÓN DIRECTA</span><span class="pill">8 EQUIPOS</span></div>`}
function renderBoard(){if(!career)return;$('financeBudget').textContent=`$${career.budget}M`;$('financeWage').textContent=`$${career.players.reduce((a,p)=>a+p.wage,0).toFixed(1)}M`;$('financeBoard').textContent=career.board+'%';$('objectives').innerHTML=`<div class="statsrow"><span>Objetivo deportivo</span><b>Top 5</b></div><div class="statsrow"><span>Objetivo financiero</span><b>No superar salarios</b></div><div class="statsrow"><span>Confianza</span><b>${career.board}%</b></div>`;$('facilities').innerHTML=`<div class="statsrow"><span>Estadio · Nivel ${career.stadium}</span><button class="btn small" onclick="upgrade('stadium')">MEJORAR · $8M</button></div><div class="statsrow"><span>Academia · Nivel ${career.academy}</span><button class="btn small" onclick="upgrade('academy')">MEJORAR · $6M</button></div><div class="statsrow"><span>Entrenamiento · Nivel ${career.training}</span><button class="btn small" onclick="upgrade('training')">MEJORAR · $5M</button></div>`;$('inbox').innerHTML=career.inbox.map(x=>`<div class="news"><div class="newsicon">✉️</div><div><p style="color:#e9eef6;margin:0">${x}</p></div></div>`).join('')}
function upgrade(type){let cost=type==='stadium'?8:type==='academy'?6:5;if(career.budget<cost){alert('Presupuesto insuficiente.');return}career.budget-=cost;career[type]++;career.inbox.unshift(`Mejora completada: ${type==='stadium'?'Estadio':type==='academy'?'Academia':'Centro de entrenamiento'} nivel ${career[type]}.`);save();renderBoard()}
function saveSettings(){localStorage.setItem('mc_settings',JSON.stringify({length:$('matchLength').value,currency:$('currency').value,injuries:$('injuries').value}))}
function resetGame(){
 if(!confirm(t('confirmReset')))return;
 ['modo_carrera_41','modo_carrera_4','modo_carrera_3','mc_settings'].forEach(k=>localStorage.removeItem(k));
 career=null;match=null;selectedSpot=null;location.reload();
}
function openModal(html){$('sheet').innerHTML=html;$('modal').classList.add('open')}function closeModal(){$('modal').classList.remove('open')}

let advancedView='academy';
function advancedTab(v,b){advancedView=v;document.querySelectorAll('#advancedTabs button').forEach(x=>x.classList.remove('active'));if(b)b.classList.add('active');renderAdvanced()}
function renderAdvanced(){if(!career)return;let c=$('advancedContent'),y=career.academyPlayers||[];
if(advancedView==='academy'){c.innerHTML=`<div class="metric-grid"><div class="metric"><b>${y.length}</b><small>JUVENILES</small></div><div class="metric"><b>${career.academy||1}</b><small>ACADEMIA</small></div><div class="metric"><b>${career.youthIntake||0}</b><small>PROMOCIONES</small></div></div><div class="card"><h2>Cantera U15 · U17 · U20</h2><button class="btn" onclick="youthIntake()">CAPTAR 3 JUVENILES · $1M</button><button class="btn secondary" onclick="academyReport()">INFORME DE DESARROLLO</button>${y.map((p,i)=>`<div class="playerrow"><div class="rating">${p.rating}</div><div class="grow"><b>${p.name}</b><div class="pos">${p.category} · ${p.pos} · ${p.age} años · POT ${p.potential}</div></div><button class="btn small" onclick="promoteYouth(${i})">PROMOVER</button></div>`).join('')||'<p class="muted">Todavía no hay juveniles.</p>'}</div><div class="card"><h2>Instalaciones</h2>${Object.entries(career.facilities||{}).map(([k,v])=>`<div class="statsrow"><span>${k} · Nivel ${v}</span><button class="btn small secondary" onclick="upgradeFacility('${k}')">MEJORAR</button></div>`).join('')}</div>`}
else if(advancedView==='scouting'){c.innerHTML=`<div class="card"><h2>Scouting internacional</h2><select id="scoutRegion"><option>Argentina</option><option>Sudamérica</option><option>Europa</option><option>África</option><option>Asia</option><option>Norteamérica</option></select><select id="scoutFocus"><option>Jóvenes promesas</option><option>Primer equipo</option><option>Defensores</option><option>Mediocampistas</option><option>Delanteros</option><option>Arqueros</option></select><button class="btn" onclick="assignScout()">ASIGNAR OJEADOR · $0.5M</button><button class="btn secondary" onclick="scoutReport()">RECIBIR INFORME</button>${(career.scouting||[]).map(s=>`<div class="statsrow">${s.region} · ${s.focus} <b>${s.weeks} semanas</b></div>`).join('')}</div>`}
else if(advancedView==='staff'){c.innerHTML=`<div class="card"><h2>Personal del club</h2>${Object.entries(career.staff||{}).map(([k,v])=>`<div class="statsrow"><span>${k}</span><b>Nivel ${v}</b><button class="btn small secondary" onclick="upgradeStaff('${k}')">MEJORAR</button></div>`).join('')}<p class="muted">El cuerpo técnico mejora desarrollo, scouting y recuperación.</p></div><div class="card"><h2>Director deportivo</h2><button class="btn" onclick="career.delegatedTransfers=true;career.inbox.unshift('Director deportivo: gestión delegada activada.');save();renderAdvanced()">DELEGAR MERCADO</button></div>`}
else if(advancedView==='press'){c.innerHTML=`<div class="card"><h2>Conferencia de prensa</h2><div class="statsrow">Reputación mediática <b>${career.pressReputation||50}/100</b></div><button class="btn secondary" onclick="pressAnswer('ambitious')">“Vamos por el campeonato”</button><button class="btn secondary" onclick="pressAnswer('calm')">“Partido a partido”</button><button class="btn secondary" onclick="pressAnswer('protect')">“Confío en mis jugadores”</button></div><div class="card"><h2>Noticias y rumores</h2>${career.inbox.slice(0,8).map(x=>`<div class="news">${x}</div>`).join('')}</div>`}
else if(advancedView==='world'){c.innerHTML=`<div class="card"><h2>Copas continentales</h2>${['CONMEBOL Libertadores','CONMEBOL Sudamericana','UEFA Champions League','UEFA Europa League','CONCACAF Champions Cup'].map(x=>`<div class="statsrow">${x}<b>${career.country==='Argentina'&&x.startsWith('CONMEBOL')?'Objetivo de clasificación':'Seguimiento'}</b></div>`).join('')}<p class="muted">La clasificación depende del rendimiento liguero. Los cuadros completos y licencias oficiales aún no están integrados.</p></div><div class="card"><h2>Selecciones nacionales</h2><button class="btn secondary" onclick="nationalCallups()">REVISAR CONVOCATORIAS</button></div>`}
else{c.innerHTML=`<div class="card"><h2>Historia del club</h2><div class="metric-grid"><div class="metric"><b>${career.w}</b><small>VICTORIAS</small></div><div class="metric"><b>${career.d}</b><small>EMPATES</small></div><div class="metric"><b>${career.l}</b><small>DERROTAS</small></div></div><div class="statsrow">Goles a favor <b>${career.gf}</b></div><div class="statsrow">Goles en contra <b>${career.ga}</b></div>${career.history.slice(-15).reverse().map(h=>`<div class="statsrow">${h.opp}<b>${h.h}-${h.a} · ${h.result}</b></div>`).join('')}</div>`}}
function youthIntake(){alert('No se generan juveniles ficticios. Incorporá futbolistas reales desde el administrador.');}
function promoteYouth(i){let p=career.academyPlayers[i];if(career.players.length>=30){alert('Plantel máximo: 30 jugadores');return}career.players.push({...p,id:Date.now(),number:career.players.length+1,fitness:95,morale:80,contract:3,wage:.2,goals:0,assists:0,apps:0});career.academyPlayers.splice(i,1);career.youthIntake=(career.youthIntake||0)+1;save();renderAdvanced();renderSquad()}
function academyReport(){career.academyPlayers.forEach(p=>{p.rating=Math.min(p.potential,p.rating+1+Math.floor(Math.random()*2))});career.inbox.unshift('Informe de cantera: se actualizaron los progresos juveniles.');save();renderAdvanced()}
function upgradeFacility(k){let v=career.facilities[k]||1,cost=v*2+2;if(career.budget<cost){alert('Presupuesto insuficiente');return}career.budget-=cost;career.facilities[k]=v+1;save();renderAdvanced()}
function assignScout(){if(career.budget<.5){alert('Presupuesto insuficiente');return}career.budget-=.5;career.scouting=career.scouting||[];career.scouting.push({region:$('scoutRegion').value,focus:$('scoutFocus').value,weeks:4});save();renderAdvanced()}
function scoutReport(){alert('El scouting no genera jugadores ficticios. Usá la base de futbolistas reales.');}
function upgradeStaff(k){let v=career.staff[k]||1,cost=v*2+2;if(career.budget<cost){alert('Presupuesto insuficiente');return}career.budget-=cost;career.staff[k]=v+1;save();renderAdvanced()}
function pressAnswer(v){career.pressReputation=Math.min(100,(career.pressReputation||50)+(v==='ambitious'?4:2));career.players.forEach(p=>p.morale=Math.min(100,p.morale+(v==='protect'?3:1)));career.inbox.unshift('Conferencia de prensa realizada.');save();renderAdvanced()}
function nationalCallups(){let a=career.players.filter(p=>p.rating>=82).slice(0,5);career.inbox.unshift(a.length?'Convocados: '+a.map(p=>p.name).join(', '):'Todavía no hay jugadores con nivel de selección.');save();renderAdvanced()}
function trainPlayer(i){let p=career.players[i];p.fitness=Math.max(50,p.fitness-8);let k=p.pos==='DEL'?'shooting':p.pos==='DEF'?'defending':'passing';p[k]=Math.min(99,(p[k]||60)+2);if(Math.random()<.2)p.rating=Math.min(99,p.rating+1);save();openPlayer(i)}
function recoverPlayer(i){let p=career.players[i];p.fitness=Math.min(100,p.fitness+20);if(p.injury)p.injury=null;save();openPlayer(i)}
function renewPlayer(i){let p=career.players[i],y=prompt('Años de contrato (1 a 5)','3');if(y===null)return;p.contract=Math.max(1,Math.min(5,+y||3));p.wage=+(p.wage*1.1).toFixed(2);save();openPlayer(i)}
function listPlayerSale(i){career.players[i].transferListed=true;career.inbox.unshift(career.players[i].name+' fue puesto en la lista de transferibles.');save();openPlayer(i)}

function renderAll(){[renderHome,renderDashboard,renderTactics,renderSquad,renderMarket,renderBoard,renderLeague,applyLanguage].forEach(f=>{try{f()}catch(e){console.warn(e)}})}

