function currentLang(){return localStorage.getItem('mc_language')||'es'}
function t(k){return (LANG[currentLang()]||LANG.es)[k]||LANG.es[k]||k}
function setLanguage(v){localStorage.setItem('mc_language',v);renderAll();if(match)renderMatch();applyLanguage();saveSettings()}
function translatePhrase(s,dict){let out=s;const keys=Object.keys(dict).sort((a,b)=>b.length-a.length);for(const k of keys){if(out.includes(k))out=out.split(k).join(dict[k]);}return out}

function translateAddedNode(root){
 const v=currentLang(),dict=WORDS[v]||{};
 if(v==='es')return;
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
 while(walker.nextNode()){
  const n=walker.currentNode;
  if(!n.nodeValue.trim())continue;
  if(!n.__original)n.__original=n.nodeValue;
  n.nodeValue=translatePhrase(n.__original,dict);
 }
 if(root.nodeType===1){
  ['placeholder','title','aria-label'].forEach(a=>{
   if(root.hasAttribute(a)){
    const key='orig_'+a;
    if(!root.dataset[key])root.dataset[key]=root.getAttribute(a);
    root.setAttribute(a,translatePhrase(root.dataset[key],dict));
   }
  });
  root.querySelectorAll('input,button,[title],[aria-label]').forEach(el=>{
   ['placeholder','title','aria-label'].forEach(a=>{
    if(el.hasAttribute(a)){
     const key='orig_'+a;
     if(!el.dataset[key])el.dataset[key]=el.getAttribute(a);
     el.setAttribute(a,translatePhrase(el.dataset[key],dict));
    }
   });
  });
 }
}
function applyLanguage(){
 const v=currentLang(), dict=WORDS[v]||{}, rtl=v==='he';
 document.documentElement.lang=v;document.documentElement.dir=rtl?'rtl':'ltr';document.body.dir=rtl?'rtl':'ltr';
 document.body.style.textAlign='';
 document.querySelectorAll('.nav button').forEach((b,i)=>{let icon=b.querySelector('i');b.innerHTML=(icon?icon.outerHTML:'')+LANG[v].nav[i]});
 const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
 nodes.forEach(n=>{if(!n.nodeValue.trim())return;if(!n.__original)n.__original=n.nodeValue;n.nodeValue=v==='es'?n.__original:translatePhrase(n.__original,dict)});
 document.querySelectorAll('input,option,button').forEach(el=>{['placeholder','title'].forEach(a=>{if(el.hasAttribute(a)){if(!el.dataset['orig'+a])el.dataset['orig'+a]=el.getAttribute(a);el.setAttribute(a,v==='es'?el.dataset['orig'+a]:translatePhrase(el.dataset['orig'+a],dict))}})});
 let danger=document.querySelector('.btn.danger');if(danger)danger.textContent=LANG[v].reset;
 let selector=document.getElementById('language');if(selector)selector.value=v;
 document.querySelectorAll('.page').forEach(p=>p.style.direction=rtl?'rtl':'ltr');
 document.querySelectorAll('.statsrow,.playerrow,.news,.between').forEach(e=>e.style.direction=rtl?'rtl':'ltr');
}
function selectHomeLeague(country){document.querySelectorAll('.home-league').forEach(b=>b.classList.toggle('selected',b.textContent.includes(({Argentina:'LIGA',Inglaterra:'PREMIER',España:'LALIGA',Italia:'SERIE',Alemania:'BUNDESLIGA',Francia:'LIGUE',Brasil:'BRASILEIRÃO','Estados Unidos':'MLS'})[country])));go('newcareer');$('country').value=country;fillClubs();}
function load(){document.body.classList.add('home-mode');try{career=JSON.parse(localStorage.getItem('modo_carrera_41'))}catch(e){career=null}fillClubs();let s={};try{s=JSON.parse(localStorage.getItem('mc_settings'))||{}}catch(e){}if(s.length)$('matchLength').value=s.length;if(s.currency)$('currency').value=s.currency;if(s.injuries)$('injuries').value=s.injuries;if(career){career.academyPlayers=career.academyPlayers||[];career.scouting=career.scouting||[];career.staff=career.staff||{coach:2,scout:1,medical:1,analyst:1};career.facilities=career.facilities||{trainingPitches:1,gym:1,medical:1,analysis:1,residence:1};career.sponsors=career.sponsors||[{name:'Patrocinador principal',income:3,level:1}];career.pressReputation=career.pressReputation||50;career.players=(career.players||[]).map(p=>({...p,pace:p.pace||60,shooting:p.shooting||60,passing:p.passing||60,defending:p.defending||60,stamina:p.stamina||70,strength:p.strength||65,injury:p.injury||null}));renderAll();$('seasonText').textContent=`TEMPORADA ${career.season}/${String(career.season+1).slice(-2)} · ${career.played?'EN CURSO':'PRETEMPORADA'}`}}
buildLeagueUI();$('country').value='Argentina';fillClubs();load();applyLanguage();
const dynamicTranslationObserver=new MutationObserver(records=>{
 if(currentLang()==='es')return;
 records.forEach(record=>record.addedNodes.forEach(node=>{
  if(node.nodeType===1||node.nodeType===3)translateAddedNode(node);
 }));
});
dynamicTranslationObserver.observe(document.body,{childList:true,subtree:true});


